//! Replays `fixtures/oracle.txt`, a transcript generated by `fixtures/gen.php`
//! with the reference PHP binary, and checks every result bit for bit.

use php_random::state::StateValue;
use php_random::{
    Engine, IntervalBoundary, Mt19937, NativeEngine, PcgOneseq128XslRr64, RandomGlobals,
    Randomizer, Seed, UserEngine, UserGenerate, Xoshiro256StarStar,
};
use std::fmt::Write;

const ORACLE: &str = include_str!("fixtures/oracle.txt");

fn unhex(s: &str) -> Vec<u8> {
    if s == "-" {
        return Vec::new();
    }
    (0..s.len())
        .step_by(2)
        .map(|i| u8::from_str_radix(&s[i..i + 2], 16).unwrap())
        .collect()
}

fn hex(b: &[u8]) -> String {
    if b.is_empty() {
        return "-".into();
    }
    b.iter().fold(String::new(), |mut s, x| {
        let _ = write!(s, "{x:02x}");
        s
    })
}

fn fbits(f: f64) -> String {
    format!("{:016x}", f.to_bits())
}

fn float_of(s: &str) -> f64 {
    f64::from_bits(u64::from_str_radix(s, 16).unwrap())
}

fn boundary(s: &str) -> IntervalBoundary {
    match s {
        "ClosedOpen" => IntervalBoundary::ClosedOpen,
        "ClosedClosed" => IntervalBoundary::ClosedClosed,
        "OpenClosed" => IntervalBoundary::OpenClosed,
        "OpenOpen" => IntervalBoundary::OpenOpen,
        other => panic!("bad boundary {other}"),
    }
}

/// The slot map of an array built as `[0, 1, ..., n-1]` with the `0`
/// positions of `mask` unset (trailing holes shrink `nNumUsed`).
fn slots(mask: &str) -> Vec<bool> {
    let mut v: Vec<bool> = mask.bytes().map(|b| b == b'1').collect();
    while v.last() == Some(&false) {
        v.pop();
    }
    v
}

fn join<T: ToString>(v: &[T]) -> String {
    v.iter()
        .map(ToString::to_string)
        .collect::<Vec<_>>()
        .join(",")
}

fn ser_line(state: &[StateValue]) -> String {
    let render = |v: &StateValue| match v {
        StateValue::Int(i) => i.to_string(),
        StateValue::Str(s) => String::from_utf8(s.clone()).unwrap(),
        StateValue::Other => "?".into(),
    };
    let parts: Vec<String> = if state.len() > 100 {
        state[..8]
            .iter()
            .chain(&state[state.len() - 4..])
            .map(render)
            .collect()
    } else {
        state.iter().map(render).collect()
    };
    parts.join(",")
}

/// The userland `SizedEngine` of gen.php.
struct SizedGen {
    inner: Xoshiro256StarStar,
    sizes: Vec<usize>,
    i: usize,
}

impl UserGenerate for SizedGen {
    fn call_generate(&mut self) -> php_random::Result<Vec<u8>> {
        let n = self.sizes[self.i % self.sizes.len()];
        self.i += 1;
        let mut b = Vec::new();
        while b.len() < n {
            b.extend_from_slice(&self.inner.next_u64().to_le_bytes());
        }
        b.truncate(n);
        Ok(b)
    }
}

enum Current {
    Native(NativeEngine),
    User(UserEngine<SizedGen>),
}

impl Current {
    fn engine(&mut self) -> &mut dyn Engine {
        match self {
            Self::Native(e) => e,
            Self::User(e) => e,
        }
    }

    fn native(&mut self) -> &mut NativeEngine {
        match self {
            Self::Native(e) => e,
            Self::User(_) => panic!("not a native engine"),
        }
    }
}

#[allow(clippy::too_many_lines)]
fn run_engine_op(cur: &mut Current, op: &str, args: &[&str], expected: &str) -> String {
    let mut r = Randomizer::new(cur.engine());
    let int = |i: usize| args[i].parse::<i64>().unwrap();
    match op {
        "gen" => hex(&r.engine.generate_bytes().unwrap()),
        "gens" => (0..expected.split(',').count())
            .map(|_| hex(&r.engine.generate_bytes().unwrap()))
            .collect::<Vec<_>>()
            .join(","),
        "int" => r.get_int(int(0), int(1)).unwrap().to_string(),
        "nextint" => r.next_int().unwrap().to_string(),
        "bytes" => hex(&r.get_bytes(int(0)).unwrap()),
        "bfs" => hex(&r.get_bytes_from_string(&unhex(args[0]), int(1)).unwrap()),
        "nextfloat" => fbits(r.next_float().unwrap()),
        "float" => match r.get_float(float_of(args[0]), float_of(args[1]), boundary(args[2])) {
            Ok(v) => fbits(v),
            Err(_) => "ERR".into(),
        },
        "shuffle" => {
            let n = usize::try_from(int(0)).unwrap().max(1);
            let mut v: Vec<usize> = (0..n).collect();
            r.shuffle_array(&mut v).unwrap();
            join(&v)
        }
        "shufbytes" => hex(&r.shuffle_bytes(&unhex(args[0])).unwrap()),
        "pick" => join(&r.pick_array_keys(&slots(args[0]), int(1)).unwrap()),
        "ser" => ser_line(&cur.native().serialize_state().unwrap()),
        "jump" => {
            match cur.native() {
                NativeEngine::Pcg(e) => e.jump(int(0)).unwrap(),
                NativeEngine::Xoshiro(e) => e.jump(),
                _ => panic!("jump on wrong engine"),
            }
            String::new()
        }
        "jumplong" => {
            match cur.native() {
                NativeEngine::Xoshiro(e) => e.jump_long(),
                _ => panic!("jumpLong on wrong engine"),
            }
            String::new()
        }
        "skip" => {
            for _ in 0..int(0) {
                r.engine.generate().unwrap();
            }
            String::new()
        }
        other => panic!("unknown op {other}"),
    }
}

fn run_global_op(g: &mut RandomGlobals, op: &str, args: &[&str]) -> String {
    let int = |i: usize| args[i].parse::<i64>().unwrap();
    match (op, args.len()) {
        ("mt_rand" | "rand", 0) => g.mt_rand().to_string(),
        ("mt_rand", 2) => g.mt_rand_range(int(0), int(1)).unwrap().to_string(),
        ("rand", 2) => g.rand_range(int(0), int(1)).to_string(),
        ("g_shuffle", 1) => {
            let n = usize::try_from(int(0)).unwrap();
            let mut v: Vec<usize> = (0..n).collect();
            g.shuffle(&mut v);
            join(&v)
        }
        ("str_shuffle", 1) => hex(&g.str_shuffle(&unhex(args[0]))),
        ("array_rand", 2) => join(&g.array_rand(&slots(args[0]), int(1)).unwrap()),
        ("g_skip", 1) => {
            for _ in 0..int(0) {
                g.mt_rand();
            }
            String::new()
        }
        _ => panic!("unknown global op {op}"),
    }
}

#[test]
fn replay_oracle_transcript() {
    let mut engine: Option<Current> = None;
    let mut globals = RandomGlobals::new();
    let mut checked = 0usize;
    for (lineno, line) in ORACLE.lines().enumerate() {
        let (lhs, expected) = match line.split_once(" = ") {
            Some((l, e)) => (l, e),
            None => (line, ""),
        };
        let words: Vec<&str> = lhs.split(' ').collect();
        let (op, args) = (words[0], &words[1..]);
        let got = match op {
            "new" => {
                if args[0] == "user" {
                    engine = Some(Current::User(UserEngine(SizedGen {
                        inner: Xoshiro256StarStar::from_seed64(args[1].parse().unwrap()),
                        sizes: args[2].split(',').map(|x| x.parse().unwrap()).collect(),
                        i: 0,
                    })));
                    continue;
                }
                let e = match (args[0], args[1]) {
                    ("mt", seed) => NativeEngine::Mt19937(Box::new(
                        Mt19937::construct(Some(seed.parse().unwrap()), args[2].parse().unwrap())
                            .unwrap(),
                    )),
                    ("pcg", "int") => NativeEngine::Pcg(
                        PcgOneseq128XslRr64::construct(Seed::Int(args[2].parse().unwrap()))
                            .unwrap(),
                    ),
                    ("pcg", "str") => NativeEngine::Pcg(
                        PcgOneseq128XslRr64::construct(Seed::Bytes(&unhex(args[2]))).unwrap(),
                    ),
                    ("xo", "int") => NativeEngine::Xoshiro(
                        Xoshiro256StarStar::construct(Seed::Int(args[2].parse().unwrap())).unwrap(),
                    ),
                    ("xo", "str") => NativeEngine::Xoshiro(
                        Xoshiro256StarStar::construct(Seed::Bytes(&unhex(args[2]))).unwrap(),
                    ),
                    other => panic!("bad engine {other:?}"),
                };
                engine = Some(Current::Native(e));
                continue;
            }
            "mt_srand" => {
                globals.mt_srand(Some(args[0].parse().unwrap()), args[1].parse().unwrap());
                continue;
            }
            "mt_rand" | "rand" | "g_shuffle" | "str_shuffle" | "array_rand" | "g_skip" => {
                run_global_op(&mut globals, op, args)
            }
            _ => run_engine_op(engine.as_mut().unwrap(), op, args, expected),
        };
        assert_eq!(got, expected, "line {}: {line}", lineno + 1);
        checked += 1;
    }
    assert!(checked > 6000, "only {checked} checks");
}
